import { cx } from "@/components/ui";

/**
 * Layered cinematic background: navy-black sky, copper topographic contours,
 * amber horizon glow, and layered mountains/forest (vector assets generated by
 * scripts/generate-wilderness-assets.mjs).
 *
 * `full`  — onboarding / sign-in: the complete composition.
 * `quiet` — interior pages: same identity, lowered so content leads.
 */
export function WildernessBackdrop({
  variant = "full",
}: {
  variant?: "full" | "quiet";
}) {
  const full = variant === "full";
  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 -z-10 overflow-hidden bg-night"
    >
      {/* Sky */}
      <div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 70% at 50% 0%, #0a1a24 0%, #050d13 55%, #03080c 100%), linear-gradient(180deg, #040b11 0%, #06110e 100%)",
        }}
      />
      {/* Topographic contours, strongest high and to the right */}
      <div
        className="absolute inset-0 bg-cover bg-center"
        style={{
          backgroundImage: "url(/brand/topo.svg)",
          opacity: full ? 0.55 : 0.22,
          maskImage: full
            ? "radial-gradient(90% 75% at 72% 22%, #000 0%, rgb(0 0 0 / 0.55) 55%, transparent 88%)"
            : "linear-gradient(180deg, #000 0%, rgb(0 0 0 / 0.5) 40%, transparent 75%)",
          WebkitMaskImage: full
            ? "radial-gradient(90% 75% at 72% 22%, #000 0%, rgb(0 0 0 / 0.55) 55%, transparent 88%)"
            : "linear-gradient(180deg, #000 0%, rgb(0 0 0 / 0.5) 40%, transparent 75%)",
        }}
      />
      {/* Warm horizon glow */}
      <div
        className="hp-glow absolute inset-0"
        style={{
          background: full
            ? "radial-gradient(42% 38% at 84% 74%, rgb(240 160 80 / 0.32) 0%, rgb(190 110 50 / 0.12) 45%, transparent 75%)"
            : "radial-gradient(45% 30% at 84% 100%, rgb(240 160 80 / 0.14) 0%, transparent 70%)",
        }}
      />
      {/* Mountains and forest */}
      {/* eslint-disable-next-line @next/next/no-img-element -- decorative static SVG */}
      <img
        src="/brand/horizon.svg"
        alt=""
        style={{
          maskImage: "linear-gradient(180deg, transparent 0%, #000 30%)",
          WebkitMaskImage: "linear-gradient(180deg, transparent 0%, #000 30%)",
        }}
        className={cx(
          "absolute bottom-0 left-0 w-full object-cover object-[78%_100%] sm:object-bottom",
          full
            ? "h-[46vh] min-h-[260px] opacity-100"
            : "h-[24vh] min-h-[150px] opacity-45",
        )}
      />
      {/* Interior pages: settle the scene so cards stay legible */}
      {!full && (
        <div
          className="absolute inset-0"
          style={{
            background:
              "linear-gradient(180deg, transparent 0%, rgb(4 11 17 / 0.35) 60%, rgb(4 11 17 / 0.55) 100%)",
          }}
        />
      )}
      {/* Vignette */}
      <div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(130% 100% at 50% 40%, transparent 55%, rgb(0 0 0 / 0.55) 100%)",
        }}
      />
    </div>
  );
}
